        impl Config { # [doc = " Return a new default Thompson NFA compiler configuration."] pub fn new () -> Config { Config :: default () } # [doc = " Whether to enable UTF-8 mode during search or not."] # [doc = ""] # [doc = " A regex engine is said to be in UTF-8 mode when it guarantees that"] # [doc = " all matches returned by it have spans consisting of only valid UTF-8."] # [doc = " That is, it is impossible for a match span to be returned that"] # [doc = " contains any invalid UTF-8."] # [doc = ""] # [doc = " UTF-8 mode generally consists of two things:"] # [doc = ""] # [doc = " 1. Whether the NFA's states are constructed such that all paths to a"] # [doc = " match state that consume at least one byte always correspond to valid"] # [doc = " UTF-8."] # [doc = " 2. Whether all paths to a match state that do _not_ consume any bytes"] # [doc = " should always correspond to valid UTF-8 boundaries."] # [doc = ""] # [doc = " (1) is a guarantee made by whoever constructs the NFA."] # [doc = " If you're parsing a regex from its concrete syntax, then"] # [doc = " [`syntax::Config::utf8`](crate::util::syntax::Config::utf8) can make"] # [doc = " this guarantee for you. It does it by returning an error if the regex"] # [doc = " pattern could every report a non-empty match span that contains invalid"] # [doc = " UTF-8. So long as `syntax::Config::utf8` mode is enabled and your regex"] # [doc = " successfully parses, then you're guaranteed that the corresponding NFA"] # [doc = " will only ever report non-empty match spans containing valid UTF-8."] # [doc = ""] # [doc = " (2) is a trickier guarantee because it cannot be enforced by the NFA"] # [doc = " state graph itself. Consider, for example, the regex `a*`. It matches"] # [doc = " the empty strings in `☃` at positions `0`, `1`, `2` and `3`, where"] # [doc = " positions `1` and `2` occur within the UTF-8 encoding of a codepoint,"] # [doc = " and thus correspond to invalid UTF-8 boundaries. Therefore, this"] # [doc = " guarantee must be made at a higher level than the NFA state graph"] # [doc = " itself. This crate deals with this case in each regex engine. Namely,"] # [doc = " when a zero-width match that splits a codepoint is found and UTF-8"] # [doc = " mode enabled, then it is ignored and the engine moves on looking for"] # [doc = " the next match."] # [doc = ""] # [doc = " Thus, UTF-8 mode is both a promise that the NFA built only reports"] # [doc = " non-empty matches that are valid UTF-8, and an *instruction* to regex"] # [doc = " engines that empty matches that split codepoints should be banned."] # [doc = ""] # [doc = " Because UTF-8 mode is fundamentally about avoiding invalid UTF-8 spans,"] # [doc = " it only makes sense to enable this option when you *know* your haystack"] # [doc = " is valid UTF-8. (For example, a `&str`.) Enabling UTF-8 mode and"] # [doc = " searching a haystack that contains invalid UTF-8 leads to **unspecified"] # [doc = " behavior**."] # [doc = ""] # [doc = " Therefore, it may make sense to enable `syntax::Config::utf8` while"] # [doc = " simultaneously *disabling* this option. That would ensure all non-empty"] # [doc = " match spans are valid UTF-8, but that empty match spans may still split"] # [doc = " a codepoint or match at other places that aren't valid UTF-8."] # [doc = ""] # [doc = " In general, this mode is only relevant if your regex can match the"] # [doc = " empty string. Most regexes don't."] # [doc = ""] # [doc = " This is enabled by default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how UTF-8 mode can impact the match spans that may"] # [doc = " be reported in certain cases."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     nfa::thompson::{self, pikevm::PikeVM},"] # [doc = "     Match, Input,"] # [doc = " };"] # [doc = ""] # [doc = " let re = PikeVM::new(\"\")?;"] # [doc = " let (mut cache, mut caps) = (re.create_cache(), re.create_captures());"] # [doc = ""] # [doc = " // UTF-8 mode is enabled by default."] # [doc = " let mut input = Input::new(\"☃\");"] # [doc = " re.search(&mut cache, &input, &mut caps);"] # [doc = " assert_eq!(Some(Match::must(0, 0..0)), caps.get_match());"] # [doc = ""] # [doc = " // Even though an empty regex matches at 1..1, our next match is"] # [doc = " // 3..3 because 1..1 and 2..2 split the snowman codepoint (which is"] # [doc = " // three bytes long)."] # [doc = " input.set_start(1);"] # [doc = " re.search(&mut cache, &input, &mut caps);"] # [doc = " assert_eq!(Some(Match::must(0, 3..3)), caps.get_match());"] # [doc = ""] # [doc = " // But if we disable UTF-8, then we'll get matches at 1..1 and 2..2:"] # [doc = " let re = PikeVM::builder()"] # [doc = "     .thompson(thompson::Config::new().utf8(false))"] # [doc = "     .build(\"\")?;"] # [doc = " re.search(&mut cache, &input, &mut caps);"] # [doc = " assert_eq!(Some(Match::must(0, 1..1)), caps.get_match());"] # [doc = ""] # [doc = " input.set_start(2);"] # [doc = " re.search(&mut cache, &input, &mut caps);"] # [doc = " assert_eq!(Some(Match::must(0, 2..2)), caps.get_match());"] # [doc = ""] # [doc = " input.set_start(3);"] # [doc = " re.search(&mut cache, &input, &mut caps);"] # [doc = " assert_eq!(Some(Match::must(0, 3..3)), caps.get_match());"] # [doc = ""] # [doc = " input.set_start(4);"] # [doc = " re.search(&mut cache, &input, &mut caps);"] # [doc = " assert_eq!(None, caps.get_match());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn utf8 (mut self , yes : bool) -> Config { self . utf8 = Some (yes) ; self } # [doc = " Reverse the NFA."] # [doc = ""] # [doc = " A NFA reversal is performed by reversing all of the concatenated"] # [doc = " sub-expressions in the original pattern, recursively. (Look around"] # [doc = " operators are also inverted.) The resulting NFA can be used to match"] # [doc = " the pattern starting from the end of a string instead of the beginning"] # [doc = " of a string."] # [doc = ""] # [doc = " Reversing the NFA is useful for building a reverse DFA, which is most"] # [doc = " useful for finding the start of a match after its ending position has"] # [doc = " been found. NFA execution engines typically do not work on reverse"] # [doc = " NFAs. For example, currently, the Pike VM reports the starting location"] # [doc = " of matches without a reverse NFA."] # [doc = ""] # [doc = " Currently, enabling this setting requires disabling the"] # [doc = " [`captures`](Config::captures) setting. If both are enabled, then the"] # [doc = " compiler will return an error. It is expected that this limitation will"] # [doc = " be lifted in the future."] # [doc = ""] # [doc = " This is disabled by default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to build a DFA from a reverse NFA, and then use"] # [doc = " the DFA to search backwards."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{self, Automaton},"] # [doc = "     nfa::thompson::{NFA, WhichCaptures},"] # [doc = "     HalfMatch, Input,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = dfa::dense::Builder::new()"] # [doc = "     .thompson(NFA::config()"] # [doc = "         .which_captures(WhichCaptures::None)"] # [doc = "         .reverse(true)"] # [doc = "     )"] # [doc = "     .build(\"baz[0-9]+\")?;"] # [doc = " let expected = Some(HalfMatch::must(0, 3));"] # [doc = " assert_eq!("] # [doc = "     expected,"] # [doc = "     dfa.try_search_rev(&Input::new(\"foobaz12345bar\"))?,"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn reverse (mut self , yes : bool) -> Config { self . reverse = Some (yes) ; self } # [doc = " Sets an approximate size limit on the total heap used by the NFA being"] # [doc = " compiled."] # [doc = ""] # [doc = " This permits imposing constraints on the size of a compiled NFA. This"] # [doc = " may be useful in contexts where the regex pattern is untrusted and one"] # [doc = " wants to avoid using too much memory."] # [doc = ""] # [doc = " This size limit does not apply to auxiliary heap used during"] # [doc = " compilation that is not part of the built NFA."] # [doc = ""] # [doc = " Note that this size limit is applied during compilation in order for"] # [doc = " the limit to prevent too much heap from being used. However, the"] # [doc = " implementation may use an intermediate NFA representation that is"] # [doc = " otherwise slightly bigger than the final public form. Since the size"] # [doc = " limit may be applied to an intermediate representation, there is not"] # [doc = " necessarily a precise correspondence between the configured size limit"] # [doc = " and the heap usage of the final NFA."] # [doc = ""] # [doc = " There is no size limit by default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example demonstrates how Unicode mode can greatly increase the"] # [doc = " size of the NFA."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::nfa::thompson::NFA;"] # [doc = ""] # [doc = " // 300KB isn't enough!"] # [doc = " NFA::compiler()"] # [doc = "     .configure(NFA::config().nfa_size_limit(Some(300_000)))"] # [doc = "     .build(r\"\\w{20}\")"] # [doc = "     .unwrap_err();"] # [doc = ""] # [doc = " // ... but 500KB probably is."] # [doc = " let nfa = NFA::compiler()"] # [doc = "     .configure(NFA::config().nfa_size_limit(Some(500_000)))"] # [doc = "     .build(r\"\\w{20}\")?;"] # [doc = ""] # [doc = " assert_eq!(nfa.pattern_len(), 1);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn nfa_size_limit (mut self , bytes : Option < usize >) -> Config { self . nfa_size_limit = Some (bytes) ; self } # [doc = " Apply best effort heuristics to shrink the NFA at the expense of more"] # [doc = " time/memory."] # [doc = ""] # [doc = " Generally speaking, if one is using an NFA to compile a DFA, then the"] # [doc = " extra time used to shrink the NFA will be more than made up for during"] # [doc = " DFA construction (potentially by a lot). In other words, enabling this"] # [doc = " can substantially decrease the overall amount of time it takes to build"] # [doc = " a DFA."] # [doc = ""] # [doc = " A reason to keep this disabled is if you want to compile an NFA and"] # [doc = " start using it as quickly as possible without needing to build a DFA,"] # [doc = " and you don't mind using a bit of extra memory for the NFA. e.g., for"] # [doc = " an NFA simulation or for a lazy DFA."] # [doc = ""] # [doc = " NFA shrinking is currently most useful when compiling a reverse"] # [doc = " NFA with large Unicode character classes. In particular, it trades"] # [doc = " additional CPU time during NFA compilation in favor of generating fewer"] # [doc = " NFA states."] # [doc = ""] # [doc = " This is disabled by default because it can increase compile times"] # [doc = " quite a bit if you aren't building a full DFA."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows that NFA shrinking can lead to substantial space"] # [doc = " savings in some cases. Notice that, as noted above, we build a reverse"] # [doc = " DFA and use a pattern with a large Unicode character class."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::nfa::thompson::{NFA, WhichCaptures};"] # [doc = ""] # [doc = " // Currently we have to disable captures when enabling reverse NFA."] # [doc = " let config = NFA::config()"] # [doc = "     .which_captures(WhichCaptures::None)"] # [doc = "     .reverse(true);"] # [doc = " let not_shrunk = NFA::compiler()"] # [doc = "     .configure(config.clone().shrink(false))"] # [doc = "     .build(r\"\\w\")?;"] # [doc = " let shrunk = NFA::compiler()"] # [doc = "     .configure(config.clone().shrink(true))"] # [doc = "     .build(r\"\\w\")?;"] # [doc = ""] # [doc = " // While a specific shrink factor is not guaranteed, the savings can be"] # [doc = " // considerable in some cases."] # [doc = " assert!(shrunk.states().len() * 2 < not_shrunk.states().len());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn shrink (mut self , yes : bool) -> Config { self . shrink = Some (yes) ; self } # [doc = " Whether to include 'Capture' states in the NFA."] # [doc = ""] # [doc = " Currently, enabling this setting requires disabling the"] # [doc = " [`reverse`](Config::reverse) setting. If both are enabled, then the"] # [doc = " compiler will return an error. It is expected that this limitation will"] # [doc = " be lifted in the future."] # [doc = ""] # [doc = " This is enabled by default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example demonstrates that some regex engines, like the Pike VM,"] # [doc = " require capturing states to be present in the NFA to report match"] # [doc = " offsets."] # [doc = ""] # [doc = " (Note that since this method is deprecated, the example below uses"] # [doc = " [`Config::which_captures`] to disable capture states.)"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::nfa::thompson::{"] # [doc = "     pikevm::PikeVM,"] # [doc = "     NFA,"] # [doc = "     WhichCaptures,"] # [doc = " };"] # [doc = ""] # [doc = " let re = PikeVM::builder()"] # [doc = "     .thompson(NFA::config().which_captures(WhichCaptures::None))"] # [doc = "     .build(r\"[a-z]+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = ""] # [doc = " assert!(re.is_match(&mut cache, \"abc\"));"] # [doc = " assert_eq!(None, re.find(&mut cache, \"abc\"));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [deprecated (since = "0.3.5" , note = "use which_captures instead")] pub fn captures (self , yes : bool) -> Config { self . which_captures (if yes { WhichCaptures :: All } else { WhichCaptures :: None }) } # [doc = " Configures what kinds of capture groups are compiled into"] # [doc = " [`State::Capture`](crate::nfa::thompson::State::Capture) states in a"] # [doc = " Thompson NFA."] # [doc = ""] # [doc = " Currently, using any option except for [`WhichCaptures::None`] requires"] # [doc = " disabling the [`reverse`](Config::reverse) setting. If both are"] # [doc = " enabled, then the compiler will return an error. It is expected that"] # [doc = " this limitation will be lifted in the future."] # [doc = ""] # [doc = " This is set to [`WhichCaptures::All`] by default. Callers may wish to"] # [doc = " use [`WhichCaptures::Implicit`] in cases where one wants avoid the"] # [doc = " overhead of capture states for explicit groups. Usually this occurs"] # [doc = " when one wants to use the `PikeVM` only for determining the overall"] # [doc = " match. Otherwise, the `PikeVM` could use much more memory than is"] # [doc = " necessary."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example demonstrates that some regex engines, like the Pike VM,"] # [doc = " require capturing states to be present in the NFA to report match"] # [doc = " offsets."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::nfa::thompson::{"] # [doc = "     pikevm::PikeVM,"] # [doc = "     NFA,"] # [doc = "     WhichCaptures,"] # [doc = " };"] # [doc = ""] # [doc = " let re = PikeVM::builder()"] # [doc = "     .thompson(NFA::config().which_captures(WhichCaptures::None))"] # [doc = "     .build(r\"[a-z]+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = ""] # [doc = " assert!(re.is_match(&mut cache, \"abc\"));"] # [doc = " assert_eq!(None, re.find(&mut cache, \"abc\"));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " The same applies to the bounded backtracker:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::nfa::thompson::{"] # [doc = "     backtrack::BoundedBacktracker,"] # [doc = "     NFA,"] # [doc = "     WhichCaptures,"] # [doc = " };"] # [doc = ""] # [doc = " let re = BoundedBacktracker::builder()"] # [doc = "     .thompson(NFA::config().which_captures(WhichCaptures::None))"] # [doc = "     .build(r\"[a-z]+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = ""] # [doc = " assert!(re.try_is_match(&mut cache, \"abc\")?);"] # [doc = " assert_eq!(None, re.try_find(&mut cache, \"abc\")?);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn which_captures (mut self , which_captures : WhichCaptures) -> Config { self . which_captures = Some (which_captures) ; self } # [doc = " Sets the look-around matcher that should be used with this NFA."] # [doc = ""] # [doc = " A look-around matcher determines how to match look-around assertions."] # [doc = " In particular, some assertions are configurable. For example, the"] # [doc = " `(?m:^)` and `(?m:$)` assertions can have their line terminator changed"] # [doc = " from the default of `\\n` to any other byte."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This shows how to change the line terminator for multi-line assertions."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     nfa::thompson::{self, pikevm::PikeVM},"] # [doc = "     util::look::LookMatcher,"] # [doc = "     Match, Input,"] # [doc = " };"] # [doc = ""] # [doc = " let mut lookm = LookMatcher::new();"] # [doc = " lookm.set_line_terminator(b'\\x00');"] # [doc = ""] # [doc = " let re = PikeVM::builder()"] # [doc = "     .thompson(thompson::Config::new().look_matcher(lookm))"] # [doc = "     .build(r\"(?m)^[a-z]+$\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = ""] # [doc = " // Multi-line assertions now use NUL as a terminator."] # [doc = " assert_eq!("] # [doc = "     Some(Match::must(0, 1..4)),"] # [doc = "     re.find(&mut cache, b\"\\x00abc\\x00\"),"] # [doc = " );"] # [doc = " // ... and \\n is no longer recognized as a terminator."] # [doc = " assert_eq!("] # [doc = "     None,"] # [doc = "     re.find(&mut cache, b\"\\nabc\\n\"),"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn look_matcher (mut self , m : LookMatcher) -> Config { self . look_matcher = Some (m) ; self } # [doc = " Whether to compile an unanchored prefix into this NFA."] # [doc = ""] # [doc = " This is enabled by default. It is made available for tests only to make"] # [doc = " it easier to unit test the output of the compiler."] # [cfg (test)] fn unanchored_prefix (mut self , yes : bool) -> Config { self . unanchored_prefix = Some (yes) ; self } # [doc = " Returns whether this configuration has enabled UTF-8 mode."] pub fn get_utf8 (& self) -> bool { self . utf8 . unwrap_or (true) } # [doc = " Returns whether this configuration has enabled reverse NFA compilation."] pub fn get_reverse (& self) -> bool { self . reverse . unwrap_or (false) } # [doc = " Return the configured NFA size limit, if it exists, in the number of"] # [doc = " bytes of heap used."] pub fn get_nfa_size_limit (& self) -> Option < usize > { self . nfa_size_limit . unwrap_or (None) } # [doc = " Return whether NFA shrinking is enabled."] pub fn get_shrink (& self) -> bool { self . shrink . unwrap_or (false) } # [doc = " Return whether NFA compilation is configured to produce capture states."] # [deprecated (since = "0.3.5" , note = "use get_which_captures instead")] pub fn get_captures (& self) -> bool { self . get_which_captures () . is_any () } # [doc = " Return what kinds of capture states will be compiled into an NFA."] pub fn get_which_captures (& self) -> WhichCaptures { self . which_captures . unwrap_or (WhichCaptures :: All) } # [doc = " Return the look-around matcher for this NFA."] pub fn get_look_matcher (& self) -> LookMatcher { self . look_matcher . clone () . unwrap_or (LookMatcher :: default ()) } # [doc = " Return whether NFA compilation is configured to include an unanchored"] # [doc = " prefix."] # [doc = ""] # [doc = " This is always false when not in test mode."] fn get_unanchored_prefix (& self) -> bool { # [cfg (test)] { self . unanchored_prefix . unwrap_or (true) } # [cfg (not (test))] { true } } # [doc = " Overwrite the default configuration such that the options in `o` are"] # [doc = " always used. If an option in `o` is not set, then the corresponding"] # [doc = " option in `self` is used. If it's not set in `self` either, then it"] # [doc = " remains not set."] pub (crate) fn overwrite (& self , o : Config) -> Config { Config { utf8 : o . utf8 . or (self . utf8) , reverse : o . reverse . or (self . reverse) , nfa_size_limit : o . nfa_size_limit . or (self . nfa_size_limit) , shrink : o . shrink . or (self . shrink) , which_captures : o . which_captures . or (self . which_captures) , look_matcher : o . look_matcher . or_else (| | self . look_matcher . clone ()) , # [cfg (test)] unanchored_prefix : o . unanchored_prefix . or (self . unanchored_prefix) , } } }
